:root {
  --color-bg: #2d4a2d;
  --color-surface: #f7f3ec;
  --color-border: #8fbc6a;
  --color-label: #7a8c6e;
  --color-value: #2d3a1e;
  --color-price: #3a6b2a;
  --color-badge-bg: #8fbc6a;
  --color-badge-text: #1a3010;
  --color-header-bg: #3a6b2a;
  --color-header-text: #f7f3ec;
}

.booking-tag {
  background-color: var(--color-surface);
  border: 3px solid var(--color-border);
  border-radius: 14px;
  width: 280px;
  overflow: hidden;
  font-size: 14px;
}

.tag-header {
  background-color: var(--color-header-bg);
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 16px;
}

.tag-icon {
  font-size: 22px;
  line-height: 1;
}

.tag-title {
  color: var(--color-header-text);
  font-size: 18px;
  font-weight: 700;
  margin: 0;
}

.tag-body {
  padding: 14px 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  border-bottom: 2px dashed var(--color-border);
}

.tag-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.tag-label {
  color: var(--color-label);
  font-weight: 600;
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.tag-value {
  color: var(--color-value);
  font-weight: 500;
}

.tag-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 16px;
}

.tag-price {
  color: var(--color-price);
  font-size: 22px;
  font-weight: 800;
}

.tag-badge {
  background-color: var(--color-badge-bg);
  color: var(--color-badge-text);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  padding: 4px 10px;
  border-radius: 20px;
}
